const resultado = app.querySelector('output');
formulario.addEventListener('submit', (evento) => {
  evento.preventDefault();
  const campos = new FormData(formulario);
  try {
    resultado.textContent = calcular(Number(campos.get('a')), campos.get('operador'), Number(campos.get('b')));
  } catch (erro) {
    resultado.textContent = erro.message;
  }
});

